import os, time, requests

BASE = os.environ["NOMUS_BASE_URL"]      # https://<<SUA_EMPRESA>>.nomus.com.br/<<SUA_EMPRESA>>/rest
CHAVE = os.environ["NOMUS_CHAVE_REST"]   # <<SUA_CHAVE_INTEGRACAO_REST>>
HEADERS = {"Authorization": f"Basic {CHAVE}", "Content-Type": "application/json"}

def get(caminho, params=None):
    while True:
        r = requests.get(f"{BASE}{caminho}", headers=HEADERS, params=params, timeout=60)
        if r.status_code == 429:
            time.sleep(int(r.json().get("tempoAteLiberar", 20)) + 1)
            continue
        r.raise_for_status()
        return r.json()

import os, time, requests

BASE = os.environ["NOMUS_BASE_URL"]      # https://<<SUA_EMPRESA>>.nomus.com.br/<<SUA_EMPRESA>>/rest
CHAVE = os.environ["NOMUS_CHAVE_REST"]   # <<SUA_CHAVE_INTEGRACAO_REST>>
HEADERS = {"Authorization": f"Basic {CHAVE}", "Content-Type": "application/json"}

def listar(caminho, query=None):
    linhas, pagina = [], 1
    while True:
        params = {"pagina": pagina, **({"query": query} if query else {})}
        lote = requests.get(f"{BASE}{caminho}", headers=HEADERS, params=params, timeout=60).json()
        linhas += lote
        if len(lote) < 50:
            return linhas
        pagina += 1
        time.sleep(20)

def br(v):
    """'11.245,57' -> 11245.57"""
    return None if v in (None, "") else float(str(v).replace(".", "").replace(",", "."))

def ponto(v):
    """'10.000000' -> 10.0"""
    return None if v in (None, "") else float(v)

